+// Sales from the till: each ticket sold some dishes; each dish uses one
+// recipe portion per qty. The stock used is stored with the sale so reports
+// do not change when a recipe is edited later.
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { AppError } from "../errors.js";
+
+/** True when the sale ticket was already imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Books one dish line of a ticket: consumes its ingredients (ref `sale:<ticket>`). Throws sale_short naming `row`. */
+export function sellDish(store, { ticket, soldAt, dishId, qty }, row) {
+  const dish = getDish(store, dishId);
+  const uses = scaled(getRecipe(store, dish.recipeId), qty);
+  for (const u of uses) {
+    const item = getItem(store, u.itemId);
+    const available = onHand(store, u.itemId);
+    if (available < u.qty) throw new AppError("sale_short", { row, item: item.name, available, unit: item.unit });
+  }
+  for (const u of uses) consume(store, u.itemId, u.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  let sale = store.data.sales.find((s) => s.ticket === ticket);
+  if (!sale) store.data.sales.push((sale = { ticket, lines: [] }));
+  sale.lines.push({ soldAt, dishId, qty, uses });
+}
